// The VOCABULARY of an agent-emission inventory (lib/derive-agent-emissions.mjs): which
// (stream, phase) pairs the gateway can put on the `agent` channel, and which `data` keys
// each one can carry — read the same way by every consumer, so they cannot disagree.
//
// Three consumers, one reading:
//   - the classification ratchet (test/emissions-coverage.test.ts): every pair and every
//     key of the promised version is classified handled / ignored / gap;
//   - the drift detector's known sets (src/providers/openclaw/agent-emission-vocabulary.ts,
//     regenerated by scripts/emission-vocabulary.mjs and held to `runtimeVocabulary` by
//     test/emission-vocabulary.test.ts);
//   - the live bench's emission check (every captured frame must exist in the inventory).
//
// The text forms are the inventory's own (`summarize` in derive-agent-emissions.mjs and
// diff-agent-emissions.mjs): `-` = no `phase` key, `<opaque>` = a value the deriver could
// not resolve. They are restated here, not imported, because those two modules spell them
// inline; `emission-vocabulary.test.ts` checks that the pairs below are exactly the
// summary's.
//
// WHAT COUNTS AS EMITTED, stated once:
//   - every emission row (its stream, its phase, its keys);
//   - every frame the gateway FABRICATES on the channel (transformations.fabricated);
//   - every key a transformation ADDS after emission, on each pair its guard admits.
// A removal (transformations.dataRemovals) is conditional, so it never removes a key from
// the vocabulary. Open entries (callers outside the analysed sources, such as the plugin
// SDK) are not vocabulary: what an external caller puts in `data` is unknowable, which is
// precisely what the drift detector exists to count.

export const NO_PHASE = "-";
export const OPAQUE = "<opaque>";

/** A row's stream as text — the inventory's own spelling. */
export function streamText(e) {
  return e.stream ?? `<opaque${e.streamOpaque?.pattern ? `:${e.streamOpaque.pattern}` : ""}>`;
}

/** A row's phase as text — the inventory's own spelling. */
export function phaseText(e) {
  return e.phaseAbsent ? NO_PHASE : e.phase === null || e.phase === undefined ? OPAQUE : String(e.phase);
}

export const pairKey = (stream, phase) => `${stream}\u0000${phase}`;

function cmp(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Does a transformation guard admit this pair? A guard is a conjunction of
 *  `{stream?: [...], phase?: [...], negated}`; an opaque value is in no literal list, so a
 *  positive test fails on it and a negated one passes. */
export function guardAdmits(guards, stream, phase) {
  for (const g of guards ?? []) {
    const tests = [];
    if (Array.isArray(g.stream)) tests.push(g.stream.includes(stream));
    if (Array.isArray(g.phase)) tests.push(g.phase.includes(phase));
    if (tests.length === 0) continue;
    const hit = tests.every(Boolean);
    if (g.negated ? hit : !hit) return false;
  }
  return true;
}

/** Every (stream, phase) pair of the inventory with its keys.
 *
 *  @returns {Map<string, {stream: string, phase: string, keys: Map<string, "always"|"optional">,
 *            sites: number, sources: Set<"emission"|"fabricated"|"rewrite">}>}
 */
export function inventoryPairs(inv) {
  const pairs = new Map();
  const at = (stream, phase) => {
    const k = pairKey(stream, phase);
    let p = pairs.get(k);
    if (!p) {
      p = { stream, phase, keys: new Map(), sites: 0, sources: new Set() };
      pairs.set(k, p);
    }
    return p;
  };
  const addKey = (p, key, optional) => {
    const prev = p.keys.get(key);
    p.keys.set(key, prev === undefined ? (optional ? "optional" : "always") : prev === "always" && !optional ? "always" : "optional");
  };
  for (const e of inv.emissions ?? []) {
    const p = at(streamText(e), phaseText(e));
    p.sites += e.lines?.length ?? 1;
    p.sources.add("emission");
    for (const k of e.keys ?? []) addKey(p, k.key, k.optional);
  }
  for (const g of inv.transformations?.fabricated ?? []) {
    const p = at(g.stream ?? OPAQUE, g.phaseAbsent ? NO_PHASE : g.phase ?? OPAQUE);
    p.sites += 1;
    p.sources.add("fabricated");
    for (const k of g.keys ?? []) addKey(p, k, false);
  }
  // Keys ADDED after emission land on the pairs the guard admits — on existing pairs
  // only: a rewrite transforms frames, it does not create a stream or a phase.
  for (const rw of inv.transformations?.dataRewrites ?? []) {
    for (const p of pairs.values()) {
      if (!guardAdmits(rw.guard, p.stream, p.phase)) continue;
      for (const k of rw.added ?? []) {
        if (!p.keys.has(k)) {
          addKey(p, k, true);
          p.sources.add("rewrite");
        }
      }
    }
  }
  return pairs;
}

/** stream → key → the phases that carry it, over every pair. */
export function streamKeys(pairs) {
  const out = new Map();
  for (const p of pairs.values()) {
    if (!out.has(p.stream)) out.set(p.stream, new Map());
    const keys = out.get(p.stream);
    for (const k of p.keys.keys()) {
      if (!keys.has(k)) keys.set(k, new Set());
      keys.get(k).add(p.phase);
    }
  }
  return out;
}

/** Chat content-part types the gateway's display projection fabricates or recognizes,
 *  spelled exactly as its literals are. */
export function chatContentPartTypes(inv) {
  const cp = inv.chatContentParts ?? {};
  return [...new Set([...(cp.fabricated ?? []), ...(cp.recognized ?? [])].map((x) => x.type))].sort(cmp);
}

/** The normalization steps a content-part fold may name, in the order they apply. */
export const CONTENT_PART_FOLD_STEPS = ["trim", "lowercase"];

/** Literals the projection compares a block's type with AFTER normalizing it (a site's
 *  `fold`, e.g. `trim+lowercase` — upstream lowercases tool block types, so `toolResult`
 *  is its `toolresult`): fold → the literals compared under it. */
export function chatContentPartFolds(inv) {
  const out = new Map();
  for (const r of inv.chatContentParts?.recognized ?? []) {
    for (const site of r.sites ?? []) {
      if (!site.fold) continue;
      const steps = site.fold.split("+");
      if (steps.some((x) => !CONTENT_PART_FOLD_STEPS.includes(x))) {
        throw new Error(`content-part fold ${JSON.stringify(site.fold)} at ${site.at} names a step this vocabulary cannot apply`);
      }
      if (!out.has(site.fold)) out.set(site.fold, new Set());
      out.get(site.fold).add(r.type);
    }
  }
  return out;
}

/** Apply a fold to a wire type, step by step (the runtime's `foldContentPartType`). */
export function foldContentPartType(fold, type) {
  let out = type;
  for (const step of fold.split("+")) {
    if (step === "trim") out = out.trim();
    else if (step === "lowercase") out = out.toLowerCase();
    else return "\u0000";
  }
  return out;
}

/** Is a content part's type known — exactly, or under a fold the projection applies? */
export function isKnownContentPartType(type, vocab) {
  if (vocab.chatContentPartTypes.includes(type)) return true;
  return Object.entries(vocab.chatContentPartFolds).some(([fold, types]) => types.includes(foldContentPartType(fold, type)));
}

const isLiteral = (s) => !s.startsWith("<");

/** The drift detector's known sets, as the UNION over the given inventories: a stream,
 *  phase or key that a supported gateway emits is not drift, whichever version emits it.
 *
 *  - `streams`: every literal stream (dotted plugin-scoped ones included; the detector
 *    skips those before it looks them up);
 *  - `phasesByStream`: per literal stream, its literal phases (no `-`, no `<opaque>`);
 *  - `keysByStream`: per literal stream, every key any of its pairs carries;
 *  - `opaqueEmitterKeys`: keys of rows whose stream the deriver could not resolve. NOT
 *    known on any stream — they were, as "keys that may arrive on any stream", and that
 *    masked every unclassified addition of the same name (review, 2026-11-08): a key is
 *    known on a stream only where a row of that stream writes it. The detector reports
 *    these apart (`opaquekey_`), as names an unresolved emitter could have added;
 *  - `chatContentPartTypes` (exact literals) and `chatContentPartFolds` (fold → literals).
 *  Rows of an opaque stream contribute no phase and no key to any stream: their candidate
 *  literals are the literal members of an OPEN union, not a closed set.
 *  Every list is sorted, so two derivations compare element by element. */
export function runtimeVocabulary(inventories) {
  const phases = new Map();
  const keys = new Map();
  const opaqueEmitter = new Set();
  const parts = new Set();
  const folds = new Map();
  const streamEntry = (s) => {
    if (!phases.has(s)) phases.set(s, new Set());
    if (!keys.has(s)) keys.set(s, new Set());
  };
  for (const inv of inventories) {
    const pairs = inventoryPairs(inv);
    for (const p of pairs.values()) {
      if (!isLiteral(p.stream)) continue;
      streamEntry(p.stream);
      if (isLiteral(p.phase) && p.phase !== NO_PHASE) phases.get(p.stream).add(p.phase);
      for (const k of p.keys.keys()) keys.get(p.stream).add(k);
    }
    for (const e of inv.emissions ?? []) {
      if (e.stream !== null && e.stream !== undefined) continue;
      for (const k of e.keys ?? []) opaqueEmitter.add(k.key);
    }
    for (const t of chatContentPartTypes(inv)) parts.add(t);
    for (const [fold, types] of chatContentPartFolds(inv)) {
      if (!folds.has(fold)) folds.set(fold, new Set());
      for (const t of types) folds.get(fold).add(t);
    }
  }
  const sortedMap = (m) => Object.fromEntries([...m.keys()].sort(cmp).map((s) => [s, [...m.get(s)].sort(cmp)]));
  return {
    streams: [...phases.keys()].sort(cmp),
    phasesByStream: sortedMap(phases),
    keysByStream: sortedMap(keys),
    opaqueEmitterKeys: [...opaqueEmitter].sort(cmp),
    chatContentPartTypes: [...parts].sort(cmp),
    chatContentPartFolds: sortedMap(folds),
  };
}

/**
 * Index one inventory for frame matching (the live bench's check): does a CAPTURED frame
 * exist in the inventory? A pair is covered by a literal row; else, weakly, by a row whose
 * phase is opaque on that stream, a row whose stream is opaque (and names this stream among
 * its candidates, or none), or an OPEN entry that can emit on this stream. A key is covered
 * by any matching row or admitted rewrite; else, weakly, by a matching row whose data is
 * opaque or an open entry whose data comes from its caller.
 */
export function frameMatcher(inv) {
  const pairs = inventoryPairs(inv);
  const opaqueStreamRows = (inv.emissions ?? []).filter((e) => e.stream === null || e.stream === undefined);
  const rowsByPair = new Map();
  for (const e of inv.emissions ?? []) {
    const k = pairKey(streamText(e), phaseText(e));
    if (!rowsByPair.has(k)) rowsByPair.set(k, []);
    rowsByPair.get(k).push(e);
  }
  const openShapes = [];
  for (const o of inv.openEntries ?? []) {
    for (const sh of o.shapes ?? []) {
      openShapes.push({ label: o.label, shape: sh });
    }
  }
  const openAdmits = (sh, stream) =>
    (sh.streams ?? []).some((x) => (x.caller ? (x.values ?? []).length === 0 || x.values.includes(stream) : x.value === stream));

  return function match(stream, phase, dataKeys) {
    const literal = pairs.get(pairKey(stream, phase));
    const weak = [];
    const opaquePhase = phase !== NO_PHASE ? pairs.get(pairKey(stream, OPAQUE)) : undefined;
    if (opaquePhase) weak.push({ via: "opaque-phase", keys: opaquePhase.keys, dataOpaque: (rowsByPair.get(pairKey(stream, OPAQUE)) ?? []).some((e) => (e.dataOpaque ?? []).length > 0) });
    for (const e of opaqueStreamRows) {
      const candidates = Array.isArray(e.streamOpaque?.literals) ? e.streamOpaque.literals : [];
      if (candidates.length > 0 && !candidates.includes(stream)) continue;
      const ph = phaseText(e);
      if (ph !== OPAQUE && ph !== phase) continue;
      weak.push({ via: "opaque-stream", keys: new Map((e.keys ?? []).map((k) => [k.key, k.optional ? "optional" : "always"])), dataOpaque: (e.dataOpaque ?? []).length > 0 });
    }
    for (const { label, shape } of openShapes) {
      if (!openAdmits(shape, stream)) continue;
      weak.push({ via: `open:${label}`, keys: new Map((shape.keys ?? []).map((k) => [k.key, k.optional ? "optional" : "always"])), dataOpaque: shape.dataFromCaller === true });
    }
    const pairVia = literal ? "literal" : weak.length > 0 ? weak[0].via : null;
    const missingKeys = [];
    const weakKeys = [];
    const opaqueKeys = [];
    for (const key of dataKeys) {
      if (literal?.keys.has(key)) continue;
      // Named, but only by a row the derivation could not pin to this pair.
      if (weak.some((w) => w.keys.has(key))) {
        weakKeys.push(key);
        continue;
      }
      const literalOpaque = literal && (rowsByPair.get(pairKey(stream, phase)) ?? []).some((e) => (e.dataOpaque ?? []).length > 0);
      if (literalOpaque || weak.some((w) => w.dataOpaque)) opaqueKeys.push(key);
      else missingKeys.push(key);
    }
    return { pair: pairVia, weakVia: literal ? [] : weak.map((w) => w.via), missingKeys, weakKeys, opaqueKeys };
  };
}

/**
 * The VENDORED view of an inventory: the extractor's full output minus the bulky audit
 * lists that explain its completeness claim identifier by identifier. Those lists are
 * reproducible (the derivation is deterministic, and `fullSha256` in PROVENANCE.json pins
 * the full output), they are 3 MB at 2026.9.36, and no consumer reads them: the diff, the
 * ratchet, the drift detector's sets and the bench check read only what is kept. The counts
 * that state the claim (`completeness.identifiers/matched/homonyms/unaccounted`) stay.
 */
export const VENDORED_DROPS = [
  "forwards",
  "completeness.byName",
  "completeness.homonymDeclarations",
  "completeness.unresolvedIdentifiers",
  "scope.testExclusion.excludedFilesMentioningFamily",
  "scope.testExclusion.reincludedByImportGuard",
  "scope.unresolvedCodeImports",
];

export function vendoredView(inv) {
  const out = structuredClone(inv);
  for (const dotted of VENDORED_DROPS) {
    const parts = dotted.split(".");
    let node = out;
    for (const p of parts.slice(0, -1)) node = node?.[p];
    if (node && typeof node === "object") delete node[parts[parts.length - 1]];
  }
  return out;
}
